package io.github.jesterportfolio.hearth.survival.housing;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
import org.bukkit.*;import org.bukkit.plugin.java.JavaPlugin;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
import io.github.jesterportfolio.hearth.survival.SurvivalWorlds;
import io.github.jesterportfolio.hearth.survival.platform.PlatformIo;
import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;
/** Metadata I/O is ordered off-thread; Bukkit world/chunk operations stay on the owner thread. */
public final class HousingWorlds implements AutoCloseable {
 private final JavaPlugin plugin;private final UUID group,realm;private final Path directory,level;private final HousingSettings settings;private final HousingProtection protection;private final Executor owner;private final PlatformIo files=new PlatformIo();private boolean closed;
 public final UnloadBackoff unloadFailures=new UnloadBackoff();
 private final Map<UUID,Chunk> tickets=new HashMap<>();private final Map<UUID,World> loaded=new HashMap<>();private final Map<UUID,Location> entries=new HashMap<>();private final Map<UUID,Long> idle=new HashMap<>();private final Map<UUID,CompletableFuture<World>> jobs=new HashMap<>();private final Set<UUID> writing=new HashSet<>();
 private record Prepared(Properties saved,RuntimeLease.Lease creation){}
 public HousingWorlds(JavaPlugin plugin,UUID group,UUID realm,HousingSettings settings,HousingProtection protection)throws Exception{this.plugin=plugin;this.group=group;this.realm=realm;this.settings=settings;this.protection=protection;owner=action->Bukkit.getScheduler().runTask(plugin,action);level=Bukkit.getServer().getLevelDirectory().toRealPath();directory=plugin.getDataFolder().toPath().toAbsolutePath().resolve("housing-worlds");if(!Files.exists(directory))Files.createDirectory(directory);if(!directory.equals(directory.toRealPath()))throw new IllegalStateException("HOUSING_PATH");}
 public Optional<UUID> house(World w){return loaded.entrySet().stream().filter(e->e.getValue()==w).map(Map.Entry::getKey).findFirst();}public Collection<World> loaded(){return List.copyOf(loaded.values());}public boolean busy(){return !jobs.isEmpty()||!writing.isEmpty()||files.pending()>0;}
 private Path file(House h){return directory.resolve(h.id()+".properties");}
 private Properties read(House h)throws Exception{Path f=file(h);if(!f.equals(f.toRealPath())||!Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS)||Files.size(f)>4096||Files.exists(directory.resolve(h.id()+".pending")))throw new IllegalStateException("HOUSING_IDENTITY_HOLD");var p=new Properties();try(var r=Files.newBufferedReader(f)){p.load(r);}if(!group.toString().equals(p.getProperty("group"))||!realm.toString().equals(p.getProperty("realm"))||!h.id().toString().equals(p.getProperty("house"))||!h.world().toString().equals(p.getProperty("world"))||!Long.toString(h.seed()).equals(p.getProperty("seed")))throw new IllegalStateException("HOUSING_IDENTITY_MISMATCH");return p;}
 private Prepared prepare(House h,NamespacedKey key,boolean provision)throws Exception{Path path=level.resolve("dimensions").resolve(key.getNamespace()).resolve(key.getKey());for(Path q=path;q!=null&&!q.equals(level);q=q.getParent())if(Files.isSymbolicLink(q))throw new IllegalStateException("HOUSING_WORLD_PATH");if(h.world()==null){if(!provision||h.phase()!=Phase.PREPARING||Files.exists(file(h),LinkOption.NOFOLLOW_LINKS)||Files.exists(path,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("HOUSING_UNKNOWN_WORLD");return new Prepared(null,RuntimeLease.acquire(directory.resolve(h.id()+".pending"),"Hearth housing creation v1\n"+h.id()+"\n").orElseThrow());}var saved=read(h);if(!path.equals(path.toRealPath())||!SurvivalWorlds.metadataUuid(path.resolve("data/paper/metadata.dat")).equals(h.world()))throw new IllegalStateException("HOUSING_WORLD_MISMATCH");return new Prepared(saved,null);}
 public CompletionStage<World> load(House h,Snapshot snapshot,boolean provision){if(closed)return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_CLOSED"));if(jobs.containsKey(h.id()))return jobs.get(h.id());if(loaded.containsKey(h.id())){if(Bukkit.getWorld(loaded.get(h.id()).getUID())!=loaded.get(h.id()))return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_HOLD"));idle.put(h.id(),System.currentTimeMillis());return CompletableFuture.completedFuture(loaded.get(h.id()));}if(loaded.size()+jobs.size()>=settings.maxLoaded())return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_CAPACITY"));var result=new CompletableFuture<World>();jobs.put(h.id(),result);var key=Objects.requireNonNull(NamespacedKey.fromString(h.key()));
  files.submit(()->prepare(h,key,provision)).thenComposeAsync(prepared->{if(closed)throw new IllegalStateException("HOUSING_CLOSED");World w=Bukkit.getWorld(key);if(h.world()==null&&w!=null)throw new IllegalStateException("HOUSING_UNKNOWN_WORLD");if(w==null)w=Objects.requireNonNull(Bukkit.createWorld(WorldCreator.ofKey(key).environment(World.Environment.NORMAL).type(WorldType.FLAT).seed(h.seed())));if(w.getSeed()!=h.seed()||h.world()!=null&&!w.getUID().equals(h.world()))throw new IllegalStateException("HOUSING_WORLD_MISMATCH");World world=w;Properties saved=prepared.saved();int cx=saved==null?0:((int)Math.floor(Double.parseDouble(saved.getProperty("x"))))>>4,cz=saved==null?0:((int)Math.floor(Double.parseDouble(saved.getProperty("z"))))>>4;
   return world.getChunkAtAsync(cx,cz,h.world()==null).thenComposeAsync(chunk->{if(closed||chunk==null)throw new IllegalStateException("HOUSING_ENTRY_CHUNK");Location at=saved==null?new Location(world,.5,world.getHighestBlockYAt(0,0)+1,.5):new Location(world,Double.parseDouble(saved.getProperty("x")),Double.parseDouble(saved.getProperty("y")),Double.parseDouble(saved.getProperty("z")));if(!inside(h,at)||!SurvivalWorlds.safe(at))throw new IllegalStateException("HOUSING_ENTRY_UNSAFE");chunk.addPluginChunkTicket(plugin);tickets.put(h.id(),chunk);world.setSpawnLocation(at);loaded.put(h.id(),world);entries.put(h.id(),at);idle.put(h.id(),System.currentTimeMillis());if(prepared.creation()==null)return CompletableFuture.completedFuture(world);world.save(true);var p=new Properties();p.setProperty("group",group.toString());p.setProperty("realm",realm.toString());p.setProperty("house",h.id().toString());p.setProperty("world",world.getUID().toString());p.setProperty("seed",Long.toString(h.seed()));coordinates(p,at);return files.submit(()->{try(var out=Files.newBufferedWriter(file(h),StandardOpenOption.CREATE_NEW)){p.store(out,"Hearth private housing v1");}force(file(h));prepared.creation().clean();return world;});},owner);
  },owner).whenCompleteAsync((world,error)->{jobs.remove(h.id());if(error!=null)result.completeExceptionally(error);else result.complete(world);},owner);return result;
 }
 private static void force(Path p)throws Exception{try(var ch=java.nio.channels.FileChannel.open(p,StandardOpenOption.WRITE)){ch.force(true);}}
 private static void coordinates(Properties p,Location at){p.setProperty("x",Double.toString(at.getX()));p.setProperty("y",Double.toString(at.getY()));p.setProperty("z",Double.toString(at.getZ()));}
 public static boolean inside(House h,Location at){double half=h.width()/2.0;return at.getX()>=-half&&at.getX()<half&&at.getZ()>=-half&&at.getZ()<half;}
 public Location entry(House h){var p=Objects.requireNonNull(entries.get(h.id())).clone();if(!inside(h,p)||!SurvivalWorlds.safe(p))throw new IllegalStateException("HOUSING_ENTRY_UNSAFE");return p;}
 public CompletionStage<Void> setEntry(House h,Location location){Location at=location.clone();if(closed||loaded.get(h.id())!=at.getWorld()||!inside(h,at)||!SurvivalWorlds.safe(at)||jobs.containsKey(h.id())||!writing.add(h.id()))return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_ENTRY_UNSAFE"));double x=at.getX(),y=at.getY(),z=at.getZ();return files.submit(()->{var before=Files.readAllBytes(file(h));var p=read(h);p.setProperty("x",Double.toString(x));p.setProperty("y",Double.toString(y));p.setProperty("z",Double.toString(z));var tmp=directory.resolve(h.id()+".new."+UUID.randomUUID());try(var out=Files.newBufferedWriter(tmp,StandardOpenOption.CREATE_NEW)){p.store(out,"Hearth private housing v1");}force(tmp);if(!Arrays.equals(before,Files.readAllBytes(file(h))))throw new IllegalStateException("HOUSING_ENTRY_EXTERNAL_CHANGE");Files.move(tmp,file(h),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);return (Void)null;}).thenRunAsync(()->{if(closed||loaded.get(h.id())!=at.getWorld())throw new IllegalStateException("HOUSING_ENTRY_STALE");var chunk=at.getChunk();chunk.addPluginChunkTicket(plugin);var previous=tickets.put(h.id(),chunk);if(previous!=null&&(previous.getWorld()!=chunk.getWorld()||previous.getX()!=chunk.getX()||previous.getZ()!=chunk.getZ()))previous.removePluginChunkTicket(plugin);entries.put(h.id(),at);at.getWorld().setSpawnLocation(at);},owner).whenCompleteAsync((v,e)->writing.remove(h.id()),owner);}
 public CompletionStage<Void> apply(House h,Snapshot snapshot){var w=Objects.requireNonNull(loaded.get(h.id()));return protection.house(h,w,snapshot).thenRunAsync(()->w.save(true),owner);}
 public CompletionStage<Void> unload(UUID id){var w=loaded.get(id);var retained=tickets.get(id);try{if(w==null)return CompletableFuture.completedFuture(null);if(Bukkit.getWorld(w.getUID())!=w)throw new IllegalStateException("HOUSING_WORLD_HOLD");if(!w.getPlayers().isEmpty()||jobs.containsKey(id)||writing.contains(id))return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_IN_USE"));w.save(true);var ticket=tickets.get(id);if(ticket!=null)ticket.removePluginChunkTicket(plugin);if(!Bukkit.unloadWorld(w,true)){if(ticket!=null)ticket.addPluginChunkTicket(plugin);return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_UNLOAD_FAILED"));}tickets.remove(id);loaded.remove(id);entries.remove(id);idle.remove(id);unloadFailures.clear(id);return CompletableFuture.completedFuture(null);}catch(Exception failure){if(w!=null&&retained!=null&&Bukkit.getWorld(w.getUID())==w)try{retained.addPluginChunkTicket(plugin);}catch(Exception restore){failure.addSuppressed(restore);}return CompletableFuture.failedFuture(failure);}}
 public void tick(){for(var item:List.copyOf(loaded.entrySet())){if(!item.getValue().getPlayers().isEmpty())idle.put(item.getKey(),System.currentTimeMillis());else if(System.currentTimeMillis()-idle.get(item.getKey())>=settings.idleSeconds()*1000L&&!jobs.containsKey(item.getKey())&&!writing.contains(item.getKey())&&unloadFailures.allowed(item.getKey(),System.currentTimeMillis()))idleUnload(item.getKey(),System.currentTimeMillis());}}
 public CompletionStage<Void> idleUnload(UUID id,long now){if(!unloadFailures.allowed(id,now))return CompletableFuture.completedFuture(null);return unload(id).whenCompleteAsync((v,error)->{if(error!=null){var f=unloadFailures.fail(id,now);plugin.getLogger().warning("HEARTH_HOUSING_UNLOAD_FAILED house="+id+" attempts="+f.attempts()+" held="+f.held());}},owner);}
 public CompletionStage<Void> drain(){if(busy())return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_BUSY"));CompletionStage<Void> work=files.submit(()->null);for(var id:List.copyOf(loaded.keySet()))work=work.thenComposeAsync(v->unload(id),owner);return work;}
 public void close(){closed=true;files.close();}
}
